from pathlib import Path
r=Path(__file__).resolve().parents[1];s=r/'frontend/src'
def edit(name,fn):
 p=s/name;p.write_text(fn(p.read_text(encoding='utf-8-sig')),encoding='utf-8')
edit('lib/全国收录.js',lambda t:t.replace("../data/全国收录.json","../data/合并人物目录.json").replace("export const people=records","export {default as summary} from '../data/人物统计摘要.json'\nexport const people=records").replace("&&x.type==='人物'",'').replace("p.provinceCode===code","(code==='unknown'?!p.provinceCode:p.provinceCode===code)"))
edit('components/山河地图.vue',lambda t:t.replace('provinces,counts,shortName','provinces,counts,shortName,summary').replace('数字为本批待复核资料条目数，不代表全国历史总人数。点击省份，查看对应名单。','三类名单合并去重，数字对应收录人物；待独立复核，不代表全国历史总人数。').replace('条资料样本','位收录人物').replace('本批资料样本','合并收录人物').replace('按资料包籍贯归类','按已记籍贯归类 · 待核地区单列').replace('<view class="atlas-layout">','<view class="scope-metrics"><view><text class="count-number">{{summary.total}}</text><text>合并收录人物</text></view><view><text class="count-number">{{summary.assigned}}</text><text>已归属省份</text></view><view @tap="go(\'province\',{code:\'unknown\'})"><text class="count-number">{{summary.unassigned}}</text><text>地区待核 ↗</text></view></view><text class="small">全国原始{{summary.nationalRaw}}条＋{{summary.dossiers}}份详细档案＋{{summary.ipGroups}}组IP（{{summary.ipPeople}}人），跨名单去重后计数。</text><view class="atlas-layout">').replace('{{counts[p.code]||0}}条','{{counts[p.code]||0}}人'))
edit('pages/statistics/index.vue',lambda t:t.replace('people,provinces','people,provinces,summary').replace('本批待复核资料条目','合并收录人物 · 待复核').replace('本次沿用第一部分资料包的119条研究样本，地图数字由同一份逐人名单计算，表示资料条目，不是全国英雄总人数，也不是独立审核通过人数。各地0条仅表示本批未收录。',"全国原始375条，合并5组重复候选后370人；再与15份详细档案、5组IP涉及的9名自然人合并。重合人物只计一次，狼牙山五壮士计5人，不额外增加一个团体。当前合计390人，分省170人、地区待核220人。不是全国历史总人数或审核通过人数。").replace('15位深度人物档案、五组学习题库与全国名单分别保存。','15位深度人物档案、五组IP人物与全国名单共用合并目录；原来源类别同时保留。').replace('按资料包所记籍贯进行省级归类。','按现有资料所记籍贯进行省级归类，缺乏依据者单列地区待核且计入总数。'))
edit('pages/province/index.vue',lambda t:t.replace('条资料样本','位收录人物').replace('找到 {{items.length}} 条资料','找到 {{items.length}} 位人物').replace("@tap=\"go('registry',{id:p.id})\"","@tap=\"p.readingId?go('person',{id:p.readingId}):go('registry',{id:p.id})\"").replace("{{p.birthYear||'未载'}}{{p.birthYear?'年':''}}","{{p.birthText||'未载'}}").replace('<text class="registry-arrow">↗</text>','<text class="small">{{p.memberships.join(\' · \')}}{{p.readingId?\' · 可深入阅读\':\'\'}}</text><text class="registry-arrow">↗</text>').replace('...provinces],province=computed(()=>provinces.find','...provinces,{code:\'unknown\',name:\'地区待核\'}],province=computed(()=>options.find').replace("provinces.some(p=>p.code===o.code)","options.some(p=>p.code===o.code)"))
edit('pages/registry/index.vue',lambda t:t.replace("import research from '../../data/研究目录.json';",'').replace("o.research==='1'?research.find(p=>p.id===o.id)||null:people.find(p=>p.id===o.id)||null","people.find(p=>p.id===o.id||p.rawIds?.includes(o.id))||null").replace('<text class="section-title">资料与依据</text>','<text class="section-title">资料与依据</text><text class="small">来源类别：{{person.memberships?.join(\' · \')}}</text><text class="small">地区依据：{{person.regionBasis}}</text>'))
edit('components/人物目录.vue',lambda t:t.replace("import records from '../data/研究目录.json';",'').replace("{provinces,shortName}","{provinces,shortName,people as records}").replace('研究条目','收录人物').replace('全国目录按资料包所记籍贯归类，375条待独立核验，不代表审核通过人数或历史总人数。同名记录保留独立编号，不强行合并。','全国名单、15份详细档案、5组IP涉及的9名人物已合并去重。地区待核人物也计入总数；不代表审核通过人数或历史总人数。').replace('与收录人物分别展示','已计入总目录，不重复增加人数').replace('条研究记录','位人物').replace("return detailMap.get(p.name)||null","return dossiers.find(d=>d.id===p.readingId)||null").replace("{id:p.id,research:'1'}","{id:p.id}").replace("{{p.birthText ? p.birthText : '出生年待补'}} · {{p.id}}","{{p.birthText ? p.birthText : '出生年待补'}} · {{p.memberships.join(' / ')}}"))
print('合并目录已接入地图、分省名单、资料页和人物检索')
